demo.program:
// Copernicus idea demo (simulated model)
var segs=['launch','cruise','flyby','arrival'];
for(var i=0;i<segs.length;i++){console.log('segment '+(i+1)+': '+segs[i]);}
console.log('mission = optimized segment chain');

// Segment demo (simulated model)
var s=[['coast',30],['burn',2.5],['coast',120]];
var tot=0;
for(var i=0;i<s.length;i++){console.log(s[i][0]+' '+s[i][1]+(s[i][0]==='burn'?' km/s':' days'));}
console.log(s.length+' segments linked');

// Shooting demo (simulated model)
var mis=100;
for(var i=0;i<5;i++){mis*=0.2;console.log('iter '+i+': mismatch '+mis.toFixed(1)+'km');}
console.log('segments stitched');

// Flyby demo (simulated model)
var vin=10, turn=60*Math.PI/180;
var vout=vin;
console.log('flyby: |v| '+vin+' km/s in, '+vout.toFixed(1)+' out, turned 60deg');
console.log('free delta-v from geometry');

// Low-thrust demo (simulated model)
var r=1.0;
for(var i=0;i<5;i++){r+=0.15;console.log('month '+(i+1)+': r='+r.toFixed(2)+' AU');}
console.log('spiral out on ion thrust');

// Multi-body demo (simulated model)
console.log('bodies: Sun, Earth, Moon in the integrator');
console.log('halo orbit converged (simulated)');

// Constraints demo (simulated model)
var c=[['launch window',1],['arrival date',1],['fuel cap',0]];
var ok=0;
for(var i=0;i<c.length;i++){if(c[i][1])ok++;console.log(c[i][0]+': '+(c[i][1]?'met':'VIOLATED'));}
console.log(ok+'/'+c.length+' constraints met');

// Porkchop demo (simulated model)
var best={c3:99,d:0};
for(var d=0;d<30;d++){var c3=12+Math.abs(d-14)*0.8;if(c3<best.c3)best={c3:c3,d:d};}
console.log('best launch day '+best.d+': C3='+best.c3.toFixed(1));
console.log('porkchop picked the window');

// C3 demo (simulated model)
var v_inf=3.5;
var c3=v_inf*v_inf;
console.log('v_inf '+v_inf+' km/s -> C3='+c3.toFixed(1)+' km^2/s^2');
console.log('launch energy quantified');

// Insertion demo (simulated model)
var vinf=2.8, rp=4000, mu=42828;
var vhyp=Math.sqrt(vinf*vinf+2*mu/rp), vcirc=Math.sqrt(mu/rp);
console.log('insertion dv='+(vhyp-vcirc).toFixed(2)+' km/s');
console.log('capture burn sized');

// Station-keeping demo (simulated model)
for(var m=0;m<3;m++){console.log('month '+m+': trim 0.05 m/s');}
console.log('halo maintained');

// Trade demo (simulated model)
var t=[['chemical',2,8],['electric',5,3]];
for(var i=0;i<t.length;i++){console.log(t[i][0]+': '+t[i][1]+'yr '+t[i][2]+'t');}
console.log('trades quantified');

// Verification demo (simulated model)
var d1=2.412, d2=2.413;
console.log('tool A '+d1+' tool B '+d2+' km/s');
console.log(Math.abs(d1-d2)<0.01?'DESIGNS AGREE':'MISMATCH');

// Proposal demo (simulated model)
console.log('fits Atlas V, 7yr cruise, fuel margin 15%');
console.log('proposal trajectory credible');

// Loop demo (simulated model)
var l=['sketch','segments','shoot','constrain','trade','verify','fly'];
for(var i=0;i<l.length;i++){console.log((i+1)+'. '+l[i]);}
console.log('design loop closed');
